public String format(LoggingEvent event) {
    if (event == null) {
        return "";
    }
    // Use a default pattern if none is set
    String pat = pattern;
    if (pat == null) {
        pat = "%d [%t] %-5p %c - %m%n";
    }
    String result = pat;
    // Replace common conversion specifiers
    result = result.replace("%m", event.getMessage() != null ? event.getMessage().toString() : "");
    result = result.replace("%p", event.getLevel() != null ? event.getLevel().toString() : "");
    result = result.replace("%c", event.getLoggerName() != null ? event.getLoggerName() : "");
    result = result.replace("%t", event.getThreadName() != null ? event.getThreadName() : "");
    result = result.replace("%n", System.lineSeparator());
    // Format the date/time
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    result = result.replace("%d", sdf.format(new java.util.Date(event.getTimeStamp())));
    // Append throwable stack trace if present
    String[] throwable = event.getThrowableStrRep();
    if (throwable != null && throwable.length > 0) {
        StringBuilder sb = new StringBuilder(result);
        sb.append(System.lineSeparator());
        for (String line : throwable) {
            sb.append(line).append(System.lineSeparator());
        }
        result = sb.toString();
    }
    return result;
}

