@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null) {
        throw new IllegalArgumentException("target graph cannot be null");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("resultMap cannot be null");
    }
    try {
        java.util.List<V> vertices = new java.util.ArrayList<>(resultMap.values());
        if (vertices.isEmpty()) {
            return;
        }
        // Add all vertices to the graph
        for (V v : vertices) {
            target.addVertex(v);
        }
        int n = vertices.size();
        int mid = n / 2;
        java.util.List<V> left = vertices.subList(0, mid);
        java.util.List<V> right = vertices.subList(mid, n);
        // Connect every vertex in left to every vertex in right
        for (V u : left) {
            for (V v : right) {
                target.addEdge(u, v);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

