public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Determine the size of the serialized message
    int size = schema.getMessageSize(message);
    // Create a CodedOutputStream to write to the OutputStream
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    // Write the length prefix as a varint
    cos.writeRawVarint32(size);
    // Serialize the message into the output stream using the provided buffer
    if (buffer != null) {
        schema.writeTo(cos, message, buffer);
    } else {
        schema.writeTo(cos, message);
    }
    // Flush the stream to ensure all bytes are written
    cos.flush();
    // Return the size of the message (excluding the length prefix)
    return size;
}

