protected List<TimeRange> buildTimeRanges(long start,long end){
    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be positive");
    }
    if (start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next;
        if (current > Long.MAX_VALUE - FETCH_DATA_DURATION) {
            next = end;
        } else {
            next = Math.min(current + FETCH_DATA_DURATION, end);
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

