public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if(byteLength <= 0){
        return this;
    }
    if(byteArrayValue != null){
        if(byteOffset < 0 || byteLength < 0 || byteOffset > byteArrayValue.length - byteLength){
            throw new IndexOutOfBoundsException("Invalid offset/length for byte array");
        }
    } else {
        if(byteOffset != 0){
            throw new IllegalArgumentException("byteOffset must be 0 when byteArrayValue is null");
        }
    }
    int newSize = size + byteLength;
    if(newSize > buffer.length){
        int newCapacity = Math.max(buffer.length * 2, newSize);
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(buffer, 0, newBuffer, 0, size);
        buffer = newBuffer;
    }
    if(byteArrayValue == null){
        for(int i = 0; i < byteLength; i++){
            buffer[size + i] = 0;
