public void removeFromTreeEdgeList() {
    // Remove this edge from the primary tree edge list
    if (prevTreeEdge != null) {
        prevTreeEdge.nextTreeEdge = nextTreeEdge;
    }
    if (nextTreeEdge != null) {
        nextTreeEdge.prevTreeEdge = prevTreeEdge;
    }

    // Remove this edge from the sibling list
    if (prevSiblingEdge != null) {
        prevSiblingEdge.nextSiblingEdge = nextSiblingEdge;
    }
    if (nextSiblingEdge != null) {
        nextSiblingEdge.prevSiblingEdge = prevSiblingEdge;
    }

    // Nullify this edge's own pointers to avoid dangling references
    prevTreeEdge = null;
    nextTreeEdge = null;
    prevSiblingEdge = null;
    nextSiblingEdge = null;
}

public static String findAndSubst(String key,Properties props){
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String subKey = matcher.group(1);
        String subValue = props.getProperty(subKey);
        if (subValue == null) {
            subValue = "";
        }
        matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(subValue));
    }
    matcher.appendTail(sb);
    return sb.toString();
}

