private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    int slots = 0;
    int i = 0;
    boolean isMethod = false;
    if (descriptor.length() > 0 && descriptor.charAt(0) == '(') {
        isMethod = true;
        i = 1; // skip '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
                }
                i = semicolon + 1;
                slots += 1;
            } else if (c == '[') {
                // skip all '['
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= descriptor.length()) {
                    throw new IllegalArgumentException("Invalid descriptor: incomplete array type");
                }
                char comp = descriptor.charAt(i);
                if (comp == 'L') {
                    int semicolon = descriptor.indexOf(';', i);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: missing ';' for array object type");
                    }
                    i = semicolon + 1;
                } else {
                    // primitive component
                    i++;
                }
                slots += 1;
            } else if (c == 'J' || c == 'D') {
                i++;
                slots += 2;
            } else {
                // primitive type
                i++;
                slots += 1;
            }
        }
        if (i >= descriptor.length() || descriptor.charAt(i) != ')') {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        // skip ')'
        i++;
        // return type is ignored for popping
    } else {
        // single type descriptor
        char c = descriptor.charAt(i);
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', i);
            if (semicolon == -1) {
                throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
            }
            i = semicolon + 1;
            slots += 1;
        } else if (c == '[') {
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= descriptor.length()) {
                throw new IllegalArgumentException("Invalid descriptor: incomplete array type");
            }
            char comp = descriptor.charAt(i);
            if (comp == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for array object type");
                }
                i = semicolon + 1;
            } else {
                i++;
            }
            slots += 1;
        } else if (c == 'J' || c == 'D') {
            i++;
            slots += 2;
        } else {
            i++;
            slots += 1;
        }
        if (i != descriptor.length()) {
            throw new IllegalArgumentException("Invalid descriptor: unexpected trailing characters");
        }
    }
    try {
        for (int j = 0; j < slots; j++) {
            outputFrameStack.pop();
        }
    } catch (java.util.EmptyStackException e) {
        throw new IllegalStateException("Attempted to pop from an empty output frame stack", e);
    }
}

@Override public void write(final byte b[],final int off,final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("b");
    }
    if (off < 0 || len < 0 || off > b.length - len) {
        throw new IndexOutOfBoundsException();
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        int newCapacity = Math.max(buf.length << 1, newCount);
        byte[] newBuf = new byte[newCapacity];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
