final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // Validate input
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
    }
    if (charBuffer == null) {
        throw new IllegalArgumentException("charBuffer cannot be null");
    }
    // Assume classFileBuffer is a byte array containing the entire class file
    // and is available as a field in this class.
    byte[] buf = classFileBuffer;
    if (buf == null || buf.length < 8) {
        throw new IllegalStateException("classFileBuffer is not initialized or too small");
    }
    int offset = 8; // skip magic(4), minor(2), major(2)
    // Read constant_pool_count
    int constantPoolCount = ((buf[offset] & 0xFF) << 8) | (buf[offset + 1] & 0xFF);
    offset += 2;
    if (constantPoolEntryIndex >= constantPoolCount) {
        throw new IllegalArgumentException("constantPoolEntryIndex out of bounds");
    }
    // Iterate through constant pool entries until we reach the desired index
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        int tag = buf[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = ((buf[offset] & 0xFF) << 8) | (buf[offset + 1] & 0xFF);
                offset += 2 + len;
                break;
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
            case 9: // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
            case 12: // CONSTANT_NameAndType
            case 15: // CONSTANT_MethodHandle
            case 16: // CONSTANT_MethodType
            case 18: // CONSTANT_InvokeDynamic
                offset += 4;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                offset += 8;
                i++; // these take up two entries
                break;
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
            case 19: // CONSTANT_Module
            case 20: // CONSTANT_Package
                offset += 2;
                break;
            default:
                throw new IllegalArgumentException("Invalid constant pool tag: " + tag);
        }
    }
    // Now at the desired entry
    int tag = buf[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
    }
    offset++;
    int length = ((buf[offset] & 0xFF) << 8) | (buf[offset + 1] & 0xFF);
    offset += 2;
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("charBuffer too small for UTF-8 string of length " + length);
    }
    int charPos = 0;
    int bytePos = offset;
    int end = bytePos + length;
    while (bytePos < end) {
        int b = buf[bytePos++] & 0xFF;
        if ((b & 0x80) == 0) {
            // 1-byte sequence
            charBuffer[charPos++] = (char) b;
        } else if ((b & 0xE0) == 0xC0) {
            // 2-byte sequence
            int b2 = buf[bytePos++] & 0xFF;
            charBuffer[charPos++] = (char) (((b & 0x1F) << 6) | (b2 & 0x3F));
        } else if ((b & 0xF0) == 0xE0) {
            // 3-byte sequence
            int b2 = buf[bytePos++] & 0xFF;
            int b3 = buf[bytePos++] & 0xFF;
            charBuffer[charPos++] = (char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F));
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 encoding at byte position " + (bytePos - 1));
        }
    }
    return new String(charBuffer, 0, charPos);
}

