private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'x':
                    // hex escape \xNN
                    if (i + 3 < len) {
                        String hex = input.substring(i + 2, i + 4);
                        try {
                            sb.append((char) Integer.parseInt(hex, 16));
                        } catch (NumberFormatException e) {
                            // keep as literal if parsing fails
                            sb.append('\\').append('x').append(hex);
                        }
                        i += 3;
                    } else {
                        sb.append('\\').append('x');
                    }
                    break;
                case 'u':
                    // unicode escape \uNNNN
                    if (i + 5 < len) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            sb.append((char) Integer.parseInt(hex, 16));
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('u').append(hex);
                        }
                        i += 5;
                    } else {
                        sb.append('\\').append('u');
                    }
                    break;
                default:
                    sb.append(next);
                    break;
            }
            i++; // skip the escaped character
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

