}

private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    // Ensure bucket 0 exists
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new java.util.HashSet<>();
        // If the list is shorter than 1, extend it
        while (bucketsByLabel.size() <= 0) {
            bucketsByLabel.add(null);
        }
        bucketsByLabel.set(0, target);
    }
    for (Integer vertex : source) {
        target.add(vertex);
        // Update label of the vertex to 0
        if (vertex >= 0 && vertex < labels.size()) {
            labels.set(vertex, 0);
        }
    }
    source.clear();
}

