void removeSelf(){
    // If this bucket is part of a doubly linked list, unlink it from its neighbors.
    if (prev != null) {
        prev.next = next;
    } else if (parent != null) {
        // If this is the first bucket, update the container's head reference.
        parent.setHead(next);
    }
    if (next != null) {
        next.prev = prev;
    } else if (parent != null) {
        // If this is the last bucket, update the container's tail reference.
        parent.setTail(prev);
    }
    // Detach this bucket from the list and the container to aid garbage collection.
    prev = null;
    next = null;
    parent = null;
}

