    return Filter.NEUTRAL;
}

public void putAllWriteable(BeanMap map){
    if (map == null) {
        return;
    }
    try {
        PropertyDescriptor[] descriptors = map.getPropertyDescriptors();
        if (descriptors == null) {
            return;
        }
        for (PropertyDescriptor pd : descriptors) {
            if (pd == null) {
                continue;
            }
            // Only consider properties that are both readable and writable
            if (pd.getReadMethod() != null && pd.getWriteMethod() != null) {
                String name = pd.getName();
                if (name == null) {
                    continue;
                }
                try {
                    Object value = map.get(name);
                    this.put(name, value);
                } catch (Exception e) {
                    // Ignore any exception while getting or putting the property
                }
            }
        }
    } catch (Exception e) {
        // Ignore any exception while retrieving property descriptors
    }
}

