private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparators = new ArrayList<>();
    if (graph == null) {
        return globalSeparators;
    }
    try {
        for (E edge : graph.getEdges()) {
            List<List<Pair<Integer,Integer>>> separators = computeMinimalSeparators(edge);
            if (separators == null) {
                continue;
            }
            for (List<Pair<Integer,Integer>> sep : separators) {
                globalSeparators.add(new Pair<>(sep, edge));
            }
        }
    } catch (Exception ex) {
        throw new RuntimeException("Failed to compute global separator list", ex);
    }
    return globalSeparators;
}

