    // Delay repaint to allow the table to paint the newly selected row
    SwingUtilities.invokeLater(() -> {
        table.repaint();
    });
}

public ByteVector putInt(final int intValue){
    int pos = this.pos;
    int cap = this.cap;
    if (pos + 4 > cap) {
        int newCap = Math.max(cap << 1, pos + 4);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(this.buf, 0, newBuf, 0, pos);
        this.buf = newBuf;
        this.cap = newCap;
    }
    this.buf[pos] = (byte) (intValue >>> 24);
    this.buf[pos + 1] = (byte) (intValue >>> 16);
    this.buf[pos + 2] = (byte) (intValue >>> 8);
    this.buf[pos + 3] = (byte) intValue;
    this.pos = pos + 4;
    return this;
}

