public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null || nameStart < 0 || nameStart > buf.length()) {
        return;
    }
    String name = buf.substring(nameStart);
    StringBuilder abbr = new StringBuilder();
    boolean next = true;
    for (int i = 0; i < name.length(); i++) {
        char c = name.charAt(i);
        if (c == '.' || c == '_' || c == '-') {
            next = true;
        } else if (next) {
            abbr.append(c);
            next = false;
        }
    }
    buf.setLength(nameStart);
    buf.append(abbr);
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    try {
        Type[] bounds = typeVariable.getBounds();
        if (bounds != null && bounds.length > 0) {
            Type bound = bounds[0];
            if (bound != null && !Object.class.equals(bound)) {
                return bound;
            }
        }
    } catch (Exception e) {
        // ignore and fall through to return Unknown
    }
    return Unknown.class;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    // Convert to list for indexed access
    List<V> vertexList = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V u = vertexList.get(i);
        if (!graph.containsVertex(u)) {
            return false;
        }
        for (int j = i + 1; j < size; j++) {
            V v = vertexList.get(j);
            if (!graph.containsVertex(v)) {
                return false;
            }
            // For undirected graphs, containsEdge(u, v) is sufficient
            if (graph.getEdge(u, v) == null) {
                return false;
            }
        }
    }
    return true;
}

