private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            bounds.add(Integer.MAX_VALUE);
            continue;
        }
        K minUpper = null;
        for (K other : keys) {
            if (other == null || other == key) continue;
            try {
                @SuppressWarnings("unchecked")
                Comparable<K> compKey = (Comparable<K>) key;
                if (compKey.compareTo(other) < 0) {
                    if (minUpper == null) {
                        minUpper = other;
                    } else {
                        @SuppressWarnings("unchecked")
                        Comparable<K> compOther = (Comparable<K>) other;
                        if (compOther.compareTo(minUpper) < 0) {
                            minUpper = other;
                        }
                    }
                }
            } catch (ClassCastException e) {
                // cannot compare, skip this pair
            }
        }
        if (minUpper != null) {
            if (minUpper instanceof Integer) {
                bounds.add(((Integer) minUpper).intValue());
            } else {
                bounds.add(minUpper.hashCode());
            }
        } else {
            bounds.add(Integer.MAX_VALUE);
        }
    }
    return bounds;
}

