public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        return null;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    boolean isAbsolute = path.startsWith("/");
    String[] pathParts = path.split("/");
    String[] relParts = relativePath.split("/");

    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    // Add existing path components to stack
    for (String part : pathParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    // Process relative path components
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    // If result is empty, return "." to represent current directory
    return result.length() == 0 ? "." : result.toString();
}

